// Package: Azure.AI.ContentSafety
// Package: Microsoft.Extensions.AI.Azure --version 9.*

using Azure.AI.ContentSafety;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Azure;

public sealed class ContentSafetyFilter
{
    private readonly ContentSafetyClient _safetyClient;
    private readonly IChatClient _chatClient;

    public ContentSafetyFilter(
        ContentSafetyClient safetyClient,
        IChatClient chatClient)
    {
        _safetyClient = safetyClient;
        _chatClient = chatClient;
    }

    public async Task<string> SafeGenerateAsync(
        string prompt,
        CancellationToken ct = default)
    {
        // Step 1: analyze input for blocked content
        var inputAnalysis = await _safetyClient.AnalyzeTextAsync(
            prompt,
            new TextAnalysisOptions { Categories = { "Hate", "Violence", "SelfHarm", "Sexual" } },
            ct);

        if (inputAnalysis.Value.Categories.Any(c => c.Severity > 3))
        {
            // Expected output: Input rejected because severity exceeded threshold
            return "Your request was flagged by content safety. Please rephrase and try again.";
        }

        // Step 2: generate response
        var response = await _chatClient.GetResponseAsync(
            new[] { new ChatMessage(ChatRole.User, prompt) },
            cancellationToken: ct);

        var answer = response.Messages.Last().Text ?? string.Empty;

        // Step 3: analyze output for blocked content
        var outputAnalysis = await _safetyClient.AnalyzeTextAsync(
            answer,
            new TextAnalysisOptions { Categories = { "Hate", "Violence", "SelfHarm", "Sexual" } },
            ct);

        if (outputAnalysis.Value.Categories.Any(c => c.Severity > 3))
        {
            // Expected output: Response replaced with safe default message
            return "I'm sorry, I cannot provide that information.";
        }

        return answer;
    }
}

// Sample usage with Microsoft.Extensions.AI.Azure abstractions:
var safetyFilter = new ContentSafetyFilter(
    new ContentSafetyClient(new Uri("https://your-content-safety.cognitiveservices.azure.com/"),
        new AzureKeyCredential("your-key")),
    new AzureAIChatClient(
        new Uri("https://your-aoai.openai.azure.com/"),
        "gpt-4o-mini",
        new AzureKeyCredential("your-key")));

var safeAnswer = await safetyFilter.SafeGenerateAsync("How do I fix a SQL injection vulnerability?");
Console.WriteLine(safeAnswer);
